  (405, 5, 1, 'iPhone Voice-to-Deploy Pipeline', 'Speaks a natural-language command from your phone, compiles the Worker via Workers AI, runs syntax checks, and pushes directly to Cloudflare.', 'Mobile-First Command & Sovereign Control Engines', 'catalog', 'Supplied Batch 5 attachment', NULL),
