  (420, 5, 16, 'Double-Entry Forensic Ledger Engine', 'Enforces strict Assets = Liabilities + Equity invariants on every transaction stored in D1 with zero floating-point drift.', 'Forensic Accounting, Ledger & Mathematical Invariant Engines', 'catalog', 'Supplied Batch 5 attachment', NULL),
