  (427, 5, 23, 'Triple-Modular Redundancy (TMR) Consensus Voter', 'Executes critical logic across three independent edge isolates and commits only when 2-of-3 or 3-of-3 agree.', 'Forensic Accounting, Ledger & Mathematical Invariant Engines', 'catalog', 'Supplied Batch 5 attachment', NULL),
  (428, 5, 24, 'CSV / Excel Forensic Diff & Reconciliation Engine', 'Compares two financial or inventory spreadsheets row-by-row and highlights exact discrepancies.', 'Forensic Accounting, Ledger & Mathematical Invariant Engines', 'catalog', 'Supplied Batch 5 attachment', NULL),
  (429, 5, 25, 'Compound Interest, Amortization & Cash-Flow Modeler', 'Computes exact payment schedules, yield curves, and net present value (NPV) JSON tables.', 'Forensic Accounting, Ledger & Mathematical Invariant Engines', 'catalog', 'Supplied Batch 5 attachment', NULL),
